-- Kelpthar Forest: quest chain fixes, hub/event spawns, cave state phasing (fork PhaseIds 161-165).
-- Sources: retail 5.5.3 sniffs (Kelpthar P1/P2), 4.3.4 client DBCs. Guid block 9001000+ (Vashj'ir).

-- ==================== 1) Quest chain semantics ====================
-- 25357 "Buy Us Some Time" + 25546 "Traveling on Our Stomachs": held concurrently, BOTH required
-- before Taylor offers 25545 (sniff) -> negative exclusive group; both follow 25405.
UPDATE `quest_template_addon` SET `PrevQuestID`=25405, `ExclusiveGroup`=-25357 WHERE `ID` IN (25357,25546);
-- 25545 "To Arms!" + 25564 "SEAL Forces": concurrent pair feeding 25547 -> negative group.
UPDATE `quest_template_addon` SET `ExclusiveGroup`=-25545 WHERE `ID` IN (25545,25564);
-- Caravan bridge: 27685 breadcrumb is optional; 25587 must not hard-require it.
UPDATE `quest_template_addon` SET `PrevQuestID`=25371 WHERE `ID` IN (25587,27685);
-- Phase recalc on quest state change for the cave-state quests.
UPDATE `quest_template` SET `Flags`=`Flags`|0x400000 WHERE `ID` IN (25281,25545,25936);

-- ==================== 2) creature_template fixes ====================
-- Abyssal Seahorse rodeo vehicle (sniff RecID 1178, bar 87217/87219/86332, spellclick flag)
UPDATE `creature_template` SET `VehicleId`=1178, `npcflag`=`npcflag`|16777216, `spell1`=87217, `spell2`=87219, `spell3`=86332 WHERE `entry`=39996;
-- 79367 is an active combat cast (sniff), not a permanent aura
UPDATE `creature_template_addon` SET `auras`=TRIM(REPLACE(CONCAT(' ', `auras`, ' '), ' 79367 ', ' ')) WHERE `entry`=40811;

-- Spellclick condition: seahorse clickable only while on The Abyssal Ride (25371)
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=18 AND `SourceGroup`=39996;
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES
(18, 39996, 86324, 0, 0, 9, 0, 25371, 0, 0, 0, 0, 0, '', 'Abyssal Seahorse spellclick only during The Abyssal Ride');

-- Gilblin Scavenger armor drops only while To Arms! is active
UPDATE `creature_loot_template` SET `QuestRequired`=1 WHERE `Entry`=40811 AND `Item` IN (54842,54843);

-- ==================== 3) Cave state phasing ====================
-- Alliance cave (The Briny Cutter, area 5012): 161=drowned bodies, 162=Taylor+recovering, 163=Taylor+soldiers.
-- Horde cave (The Immortal Coil, area 5056): 164=drowned bodies, 165=Nazgrim+recovering.
DELETE FROM `phase_area` WHERE `AreaId` IN (5012,5056) AND `PhaseId` BETWEEN 161 AND 165;
INSERT INTO `phase_area` (`AreaId`, `PhaseId`, `Comment`) VALUES
(5012, 161, 'Vashjir A-cave: drowned bodies (pre Pay It Forward)'),
(5012, 162, 'Vashjir A-cave: Taylor + recovering soldiers'),
(5012, 163, 'Vashjir A-cave: Taylor + stormwind soldiers'),
(5056, 164, 'Vashjir H-cave: drowned bodies (pre Pay It Forward)'),
(5056, 165, 'Vashjir H-cave: Nazgrim + recovering warriors');

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=26 AND `SourceGroup` BETWEEN 161 AND 165 AND `SourceEntry` IN (5012,5056);
